    train_a_interval = 16
    train_b_interval = 17

    # Find the least common multiple (LCM) of the two intervals
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def lcm(x, y):
        return x * y // gcd(x, y)

